#### Continuous Compliance Monitoring

**Automated Compliance Dashboard:**

```hcl
# terraform/compliance-dashboard.tf
resource "aws_cloudwatch_dashboard" "msk_compliance" {
  dashboard_name = "MSK-Operational-Compliance"

  dashboard_body = jsonencode({
    widgets = [
      {
        type = "metric"
        properties = {
          metrics = [
            ["MSK/Compliance", "DRDrillStatus", {stat = "Average", label = "Last DR Drill Status (1=PASS, 0=FAIL)"}],
            [".", "DaysSinceLastDRDrill", {stat = "Average", label = "Days Since Last DR Drill"}]
          ]
          period = 86400
          stat   = "Average"
          region = "us-east-1"
          title  = "DR Compliance Status"
          annotations = {
            horizontal = [{
              value = 90
              label = "Max 90 days between drills"
              fill  = "above"
              color = "#ff0000"
            }]
          }
        }
      },
      {
        type = "metric"
        properties = {
          metrics = [
            ["MSK/Compliance", "CapacityPlanningCompliance", {stat = "Average"}],
            [".", "PerformanceBenchmarkCompliance", {stat = "Average"}]
          ]
          period = 2592000  # 30 days
          stat   = "Average"
          region = "us-east-1"
          title  = "Monthly Compliance Metrics"
          yAxis  = {left = {min = 0, max = 100, label = "Compliance %"}}
        }
      },
      {
        type = "log"
        properties = {
          query = <<-EOT
            SOURCE /aws/lambda/capacity-compliance-checker
            | filter compliance_percentage < 100
            | fields @timestamp, compliance_percentage, failed_checks
            | sort @timestamp desc
            | limit 20
          EOT
          region = "us-east-1"
          title  = "Recent Compliance Failures"
        }
      }
    ]
  })
}

# Compliance metric publisher
resource "aws_cloudwatch_event_rule" "publish_compliance_metrics" {
  name                = "msk-publish-compliance-metrics"
  schedule_expression = "cron(0 0 * * ? *)"  # Daily at midnight
}

resource "aws_cloudwatch_event_target" "compliance_publisher" {
  rule      = aws_cloudwatch_event_rule.publish_compliance_metrics.name
  target_id = "PublishComplianceMetrics"
  arn       = aws_lambda_function.compliance_metric_publisher.arn
}
```

**Compliance Metric Publisher Lambda:**

```python
# lambda/compliance_metric_publisher.py
import boto3
from datetime import datetime, timedelta

cloudwatch = boto3.client('cloudwatch')
dynamodb = boto3.resource('dynamodb')

def lambda_handler(event, context):
    """
    Publish compliance metrics to CloudWatch daily.
    """
    compliance_table = dynamodb.Table('MSKComplianceRecords')

    # Calculate days since last DR drill
    last_drill = get_last_dr_drill_date()
    days_since_drill = (datetime.now() - last_drill).days

    # Get latest capacity planning compliance
    capacity_compliance = get_latest_capacity_compliance()

    # Get latest performance compliance
    performance_compliance = get_latest_performance_compliance()

    # Publish metrics
    cloudwatch.put_metric_data(
        Namespace='MSK/Compliance',
        MetricData=[
            {
                'MetricName': 'DaysSinceLastDRDrill',
                'Value': days_since_drill,
                'Unit': 'Count',
                'Timestamp': datetime.now()
            },
            {
                'MetricName': 'DRDrillStatus',
                'Value': 1 if days_since_drill <= 90 else 0,
                'Unit': 'None',
                'Timestamp': datetime.now()
            },
            {
                'MetricName': 'CapacityPlanningCompliance',
                'Value': capacity_compliance['percentage'],
                'Unit': 'Percent',
                'Timestamp': datetime.now()
            },
            {
                'MetricName': 'PerformanceBenchmarkCompliance',
                'Value': performance_compliance['percentage'],
                'Unit': 'Percent',
                'Timestamp': datetime.now()
            }
        ]
    )

    # Alert if non-compliant
    if days_since_drill > 90:
        send_compliance_alert('DR_DRILL_OVERDUE', f"Last DR drill was {days_since_drill} days ago (max 90)")

    if capacity_compliance['percentage'] < 100:
        send_compliance_alert('CAPACITY_PLANNING_NONCOMPLIANT', capacity_compliance['failed_checks'])

    return {'statusCode': 200}
```
